import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

/** Multi-turn order desk agent; callers start a conversation with orderAgent.chat(). */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  system:
    'You are the Northwind Supplies order desk. Answer customer questions about their orders using the lookupOrder tool. ' +
    'Quote the status, delivery date (the eta field) and tracking code exactly as the tool returns them. ' +
    'If an order is not found, say so. Use what the customer told you earlier in the conversation, such as their order id.',
  tools: [lookupOrder],
});
